"""Jira Cloud adapter — maps synaptory artifacts to native Jira issue types.

Mapping:
- Epic     -> Jira Epic issue type, label EPIC-001
- Story    -> Jira Story issue type, child of Epic, label US-037
- Task     -> Jira Task / Sub-task issue type
- Bug      -> Jira Bug issue type
- Sprint   -> Jira Sprint on Scrum board
- Status   -> Jira workflow statuses (To Do, In Progress, Done, etc.)
- Priority -> Jira native Priority field (Highest, High, Medium, Low, Lowest)
- Points   -> Jira story_point_estimate field

ID convention:
  The Synaptory ID (e.g. US-037) is the canonical cross-adapter identifier.
  It is stored as a `US-037` label on each issue for searchability via JQL.
  The Jira issue key (e.g. ANC-42) is an internal implementation detail.
  Issue summaries use the clean human-readable name only — no ID prefix.
"""

import json
import re
import sys
from pathlib import Path
from typing import Optional

from .base import (
    ArtifactAdapter, Epic, Story, SprintInfo, BacklogItem,
    AcceptanceCriterion, SprintMetrics, QueryFilter,
    AdapterError, AdapterAuthError, AdapterOfflineError,
)
from .transport.jira_transport import JiraTransport, _norm_status


# ── Jira Mappings ────────────────────────────────────────────────────────

# Synaptory priority -> Jira priority name
PRIORITY_MAP = {
    "Must":   "Highest",
    "Should": "High",
    "Could":  "Medium",
    "Won't":  "Low",
}
PRIORITY_REVERSE = {v: k for k, v in PRIORITY_MAP.items()}

# Synaptory status -> Jira target transition name
# These are common Jira workflow status names; the adapter resolves
# the actual transition via the issue's available transitions.
STATUS_MAP = {
    "BACKLOG":             "Backlog",
    "TO_DO":               "To Do",
    "IN_PROGRESS":         "In Progress",
    "IN_REVIEW":           "In Review",
    # #116 — projects with a configured Awaiting Acceptance workflow stage
    # land here; otherwise the adapter falls back to "In Review" via the
    # alternatives table in update_story_status.
    "AWAITING_ACCEPTANCE": "Awaiting Acceptance",
    "BLOCKED":             "Blocked",
    "DONE":                "Done",
    "COMPLETED":           "Done",  # Alias for DONE
    "CANCELLED":           "Done",  # PO cancel — board column same as DONE
}
STATUS_REVERSE = {
    "backlog":              "BACKLOG",
    "to do":                "TO_DO",
    "open":                 "TO_DO",
    "in progress":          "IN_PROGRESS",
    "in review":            "IN_REVIEW",
    "awaiting acceptance":  "AWAITING_ACCEPTANCE",
    "pending acceptance":   "AWAITING_ACCEPTANCE",
    "blocked":              "BLOCKED",
    "done":                 "DONE",
    "closed":               "DONE",
    "resolved":             "DONE",
}
# Normalized (case + separator insensitive) view of STATUS_REVERSE, so a Jira
# status "IN REVIEW" / "In-Review" reads back to its canonical state.
_STATUS_REVERSE_NORM = {_norm_status(k): v for k, v in STATUS_REVERSE.items()}

SIZE_TO_POINTS = {"S": 1, "M": 3, "L": 5, "XL": 8}
POINTS_TO_SIZE = {v: k for k, v in SIZE_TO_POINTS.items()}

# Issue type names (standard Jira Scrum types)
ISSUE_TYPES = {
    "epic":        "Epic",
    "story":       "Story",
    "task":        "Task",
    "bug":         "Bug",
    "subtask":     "Sub-task",
    "enhancement": "Story",  # No native enhancement type; use Story + label
}


_ENTITY_TYPE_PREFIXES = {
    "B-": "bug", "BUG-": "bug",
    "EPIC-": "epic",
    "T-": "task", "TASK-": "task",
}


def _detect_entity_type(entity_id: str) -> str:
    """Detect entity type from ID prefix. Returns 'story' as default."""
    upper = entity_id.upper()
    for prefix, etype in _ENTITY_TYPE_PREFIXES.items():
        if upper.startswith(prefix):
            return etype
    return "story"


def _clean_title(raw_title: str) -> str:
    """Strip the synaptory ID prefix from a title."""
    m = re.match(r'^[A-Z]+-\w+\s*[—–\-:]\s*', raw_title)
    if m:
        return raw_title[m.end():].strip()
    return raw_title


_DEFAULT_STORY_SECTIONS = [
    "Story", "Objective", "User Impact Statement",
    "Acceptance Criteria", "Business Rules", "Testing Notes",
    "Technical Context", "Data Model", "NFRs", "Feature List",
    "Dependencies", "UI Reference",
]


def _load_template_sections(template_path: str) -> list[str]:
    """Extract ## heading names from a tracker template file.

    Returns the ordered list of section headings found in the template.
    Falls back to empty list if the file doesn't exist or contains no headings.
    """
    p = Path(template_path) if template_path else None
    if not p or not p.exists():
        return []
    try:
        text = p.read_text(encoding="utf-8")
    except OSError:
        return []
    sections = []
    for line in text.splitlines():
        m = re.match(r'^##\s+(.+)', line.strip())
        if m:
            heading = m.group(1).strip()
            # Strip template placeholders like {{...}}
            heading = re.sub(r'\{\{.*?\}\}', '', heading).strip()
            if heading:
                sections.append(heading)
    return sections or []


def _build_description(entity_id: str, feature: str = "",
                       raw_text: str = "",
                       template_path: str = "") -> str:
    """Build a rich description from story/epic Markdown source.

    Returns plain text suitable for conversion to ADF by the transport.

    If template_path is provided, section ordering is derived from the
    template's ``## Heading`` lines. Otherwise, uses _DEFAULT_STORY_SECTIONS.
    """
    parts = [f"> synaptory: {entity_id}"]
    if feature:
        parts[0] += f" | Feature: {feature}"

    if raw_text:
        sections = _load_template_sections(template_path) or _DEFAULT_STORY_SECTIONS
        for section_name in sections:
            section = _extract_md_section(raw_text, section_name)
            if section:
                parts.append(f"\n## {section_name}\n\n{section}")

    return "\n".join(parts)


def _extract_md_section(text: str, heading: str) -> str:
    """Extract content under a markdown heading until next same-level heading."""
    lines = text.splitlines()
    in_section = False
    section_lines = []
    heading_level = 0
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("#"):
            hashes = len(stripped) - len(stripped.lstrip("#"))
            title = stripped.lstrip("#").strip()
            if title.lower() == heading.lower():
                in_section = True
                heading_level = hashes
                continue
            elif in_section and hashes <= heading_level:
                break
        if in_section:
            section_lines.append(line)
    return "\n".join(section_lines).strip()


class JiraAdapter(ArtifactAdapter):
    """Adapter using Jira Cloud for ticket tracking."""

    def __init__(self, project_dir: Path, config, spec=None):
        """Construct the adapter.

        spec — optional SpecConfig (multi-spec mode, see docs/multi-spec-design.md).
        When set, the adapter scopes every JQL read to the spec's filter,
        applies the corresponding write side-effect on issue creation, and
        routes its cache files to `.synaptory/.orchestrator/specs/{spec.id}/`.
        When None (legacy), the adapter behaves as before — flat cache paths,
        no JQL filter beyond `project = X`.
        """
        super().__init__(project_dir, config)
        # Spec overrides the JiraConfig used by the transport / project_key
        # / board_id. Custom-field names still come from the spec's JiraConfig.
        self.spec = spec
        jira_cfg = spec.jira if spec is not None else config.jira
        # Effective JiraConfig for this adapter (spec's when multi-spec, else
        # top-level). Carries the optional per-spec status_map override that
        # remaps canonical states onto custom Jira workflow status names.
        self._jira_cfg = jira_cfg
        self._status_map_override = dict(getattr(jira_cfg, "status_map", {}) or {})
        # Reverse view (normalized jira-name → canonical) for status read-back.
        # Normalized keys make read-back case- and separator-insensitive so
        # "IN REVIEW" reads back to IN_REVIEW without a status_map entry.
        self._status_reverse_override = {
            _norm_status(name): canon
            for canon, name in self._status_map_override.items()
        }
        # Per-entity override of the Jira issue types used to create/query
        # (e.g. a custom "Synaptory" type per entity). Empty ⇒ ISSUE_TYPES
        # defaults ⇒ unchanged behavior.
        self._issue_type_overrides = dict(getattr(jira_cfg, "issue_type_overrides", {}) or {})

        self.transport = JiraTransport(
            url=jira_cfg.url,
            project_key=jira_cfg.project_key,
        )
        self.project_key = jira_cfg.project_key
        self.story_points_field = jira_cfg.story_points_field
        self.epic_link_field = jira_cfg.epic_link_field
        self._board_id: Optional[int] = jira_cfg.board_id
        # Per-spec sprint namespace: prepended to `Sprint N` on create, and
        # used to scope every sprint read on a shared board. Empty ⇒ legacy
        # board-wide `Sprint N`. See JiraConfig.sprint_milestone_prefix.
        self._sprint_prefix: str = jira_cfg.sprint_milestone_prefix or ""
        self._id_map: Optional[dict] = None

        if spec is not None:
            spec_dir = project_dir / ".synaptory" / ".orchestrator" / "specs" / spec.id
            self._id_map_path = spec_dir / "tracker-id-map.json"
            self._backlog_order_path = spec_dir / "backlog-order.json"
            self._local_cache_path = spec_dir / "tracker-data.json"
        else:
            self._id_map_path = project_dir / ".synaptory" / ".orchestrator" / "tracker-id-map.json"
            self._backlog_order_path = project_dir / ".synaptory" / ".orchestrator" / "backlog-order.json"
            self._local_cache_path = project_dir / ".synaptory" / ".orchestrator" / "tracker-data.json"

    # ── Issue-type resolution ─────────────────────────────────

    def _jira_issue_type(self, entity_type: str) -> str:
        """Resolve the Jira issue-type name for a synaptory entity kind.

        Per-entity override (from the spec's `issue_type` config) wins;
        otherwise the built-in ISSUE_TYPES default applies, falling back to
        "Story" for unknown kinds.
        """
        return self._issue_type_overrides.get(entity_type) or ISSUE_TYPES.get(entity_type, "Story")

    # ── Spec filter helpers ──────────────────────────────────

    def _spec_filter_clause(self) -> str:
        """JQL fragment that scopes a read query to the active spec.

        Returns "" when no spec is configured. The clause is always wrapped
        in parentheses so callers can safely append `AND <clause>` without
        risking operator-precedence surprises.
        """
        if self.spec is None:
            return ""
        ftype = self.spec.filter.type
        value = self.spec.filter.value
        if ftype == "label":
            return f'(labels = "{value}")'
        if ftype == "component":
            return f'(component = "{value}")'
        if ftype == "epic":
            # Resolve synaptory epic id to Jira key if possible; fall back to raw.
            try:
                resolved = self._resolve_id(value)
            except Exception:
                resolved = None
            epic_key = resolved or value
            return f'("Epic Link" = {epic_key})'
        if ftype == "jql":
            return f'({value})'
        return ""

    def _ensure_spec_writeable(self, op: str) -> None:
        """Refuse writes when the spec's filter type is `jql` (read-only)."""
        if self.spec is not None and self.spec.filter.type == "jql":
            raise AdapterError(
                f"Spec {self.spec.id!r} uses filter.type='jql' which is read-only; "
                f"refusing {op}. Switch the spec to label/component/epic to enable writes."
            )

    def _apply_spec_write_side_effect(
        self, *, labels: list, parent_key: Optional[str] = None,
        extra_fields: Optional[dict] = None,
    ) -> tuple[list, Optional[str], dict]:
        """Apply the spec's write side-effect for issue creation.

        Returns (labels, parent_key, extra_fields) — all three usable in the
        transport `create_issue(..., labels=..., parent_key=..., fields=...)` call.

        - label     → adds the spec label to `labels` (deduped).
        - component → adds `components: [{"name": value}]` to extra_fields
                      (Jira REST API shape).
        - epic      → sets `parent_key` if the caller didn't already.
        - jql       → unreachable (refused by _ensure_spec_writeable).
        """
        extra_fields = dict(extra_fields or {})
        if self.spec is None:
            return labels, parent_key, extra_fields
        ftype = self.spec.filter.type
        value = self.spec.filter.value
        if ftype == "label":
            if value and value not in labels:
                labels.append(value)
        elif ftype == "component":
            extra_fields["components"] = [{"name": value}]
        elif ftype == "epic":
            if not parent_key:
                try:
                    resolved = self._resolve_id(value)
                except Exception:
                    resolved = None
                parent_key = resolved or value
        return labels, parent_key, extra_fields

    # ── Lifecycle ─────────────────────────────────────────────

    def initialize(self) -> None:
        """Verify auth, detect board, validate project."""
        if not self.transport.check_api():
            raise AdapterAuthError(
                "Jira API not configured. Required env vars:\n"
                "  JIRA_API_TOKEN — from https://id.atlassian.net/manage-profile/security/api-tokens\n"
                "  JIRA_USER_EMAIL — email associated with the token\n"
                "Also set tracker.jira.url and tracker.jira.project_key in .synaptory.yaml"
            )

        # Auto-detect board if not configured
        if not self._board_id:
            self._board_id = self.transport.get_board_id(self.project_key)
            if not self._board_id:
                raise AdapterError(
                    f"No Scrum board found for project {self.project_key}. "
                    f"Create a Scrum board in Jira or set tracker.jira.board_id."
                )

        self._load_id_map()

    def health_check(self) -> dict:
        h = self.transport.health_check()
        h["backend"] = "jira"
        h["board_id"] = self._board_id
        h["id_map_loaded"] = self._id_map is not None
        return h

    # ── Local Cache Write-Through ────────────────────────────

    def _update_local_cache_status(self, story_id: str, status: str) -> None:
        """Write-through: keep tracker-data.json in sync after Jira updates."""
        if not self._local_cache_path.exists():
            return
        try:
            data = json.loads(self._local_cache_path.read_text(encoding="utf-8"))
            for s in data.get("stories", []):
                if s["id"] == story_id:
                    s["status"] = status
                    break
            self._local_cache_path.write_text(
                json.dumps(data, indent=2, default=str), encoding="utf-8",
            )
        except (json.JSONDecodeError, OSError):
            pass  # cache is best-effort; don't fail the primary operation

    def sync_to_local_cache(self, sprint_num: Optional[int] = None) -> dict:
        """Pull current status from Jira and update tracker-data.json.

        Args:
            sprint_num: If given, sync only stories in that sprint.
                        If None, sync all stories.

        Returns:
            dict with sync stats: {"synced": N, "added": N, "errors": [...]}
        """
        stats: dict = {"synced": 0, "added": 0, "errors": []}
        if not self._local_cache_path.exists():
            # Bootstrap an empty cache so the first sync in a fresh workspace
            # works (#108). `migrate` is the wrong direction for new projects —
            # there's nothing local to push; the user wants to pull remote.
            self._local_cache_path.parent.mkdir(parents=True, exist_ok=True)
            self._local_cache_path.write_text(
                json.dumps({"epics": [], "sprints": [], "stories": []}, indent=2),
                encoding="utf-8",
            )

        try:
            data = json.loads(self._local_cache_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError) as e:
            stats["errors"].append(f"Failed to read local cache: {e}")
            return stats

        local_stories = {s["id"]: s for s in data.get("stories", [])}

        if sprint_num is not None:
            live_stories = self.get_sprint_backlog(sprint_num)
        else:
            live_stories = self.list_stories()

        for story in live_stories:
            if story.id in local_stories:
                local_stories[story.id]["status"] = story.status
                stats["synced"] += 1
            else:
                data["stories"].append({
                    "id": story.id, "title": story.title,
                    "feature": story.feature, "epic": story.epic,
                    "priority": story.priority, "status": story.status,
                    "size": story.size, "sprint": story.sprint,
                    "ac_count": story.ac_count, "acceptance_criteria": [],
                    "raw_text": "",
                })
                stats["added"] += 1

        try:
            self._local_cache_path.write_text(
                json.dumps(data, indent=2, default=str), encoding="utf-8",
            )
        except OSError as e:
            stats["errors"].append(f"Failed to write local cache: {e}")

        return stats

    # ── Epic Operations ──────────────────────────────────────

    def list_epics(self) -> list[Epic]:
        # Quoted — custom type names may contain spaces (e.g. "User Story").
        parts = [f'project = {self.project_key}', f'issuetype = "{self._jira_issue_type("epic")}"']
        spec_clause = self._spec_filter_clause()
        if spec_clause:
            parts.append(spec_clause)
        jql = " AND ".join(parts) + " ORDER BY created ASC"
        issues = self.transport.search_issues(jql)
        return [self._issue_to_epic(i) for i in issues]

    def get_epic(self, epic_id: str) -> Optional[Epic]:
        jira_key = self._resolve_id(epic_id)
        if not jira_key:
            return None
        try:
            issue = self.transport.get_issue(jira_key)
            return self._issue_to_epic(issue)
        except AdapterError:
            return None

    def _resolve_template_path(self, entity_type: str) -> str:
        """Resolve template path from config.templates by entity type."""
        templates_cfg = getattr(self.config, 'templates', None)
        if not templates_cfg:
            return ""
        tmpl_path = getattr(templates_cfg, entity_type, '') or ''
        if not tmpl_path and entity_type != "story":
            tmpl_path = getattr(templates_cfg, 'story', '') or ''
        if tmpl_path:
            return str(self.project_dir / tmpl_path)
        return ""

    def create_epic(self, epic: Epic, raw_text: str = "") -> Epic:
        self._ensure_spec_writeable("create_epic")
        tmpl_path = self._resolve_template_path("epic")
        description = _build_description(epic.id, raw_text=raw_text or epic.raw_text,
                                         template_path=tmpl_path)
        title = _clean_title(epic.title)

        labels: list = [epic.id]
        labels, _parent, extra_fields = self._apply_spec_write_side_effect(
            labels=labels, parent_key=None,
        )

        result = self.transport.create_issue(
            issue_type=self._jira_issue_type("epic"),
            summary=title,
            description=description,
            labels=labels,
            fields=extra_fields or None,
        )
        jira_key = result.get("key", "")
        epic.tracker_id = jira_key
        epic.tracker_url = f"{self.transport.url}/browse/{jira_key}"
        self._save_id_mapping(epic.id, jira_key, epic.tracker_url)
        return epic

    def update_epic(self, epic_id: str, **fields) -> Epic:
        jira_key = self._resolve_id(epic_id)
        if not jira_key:
            raise AdapterError(f"Epic not found in ID map: {epic_id}")
        updates = {}
        if "title" in fields:
            updates["summary"] = _clean_title(fields["title"])
        self.transport.update_issue(jira_key, **updates)
        return self.get_epic(epic_id) or Epic(id=epic_id, title=fields.get("title", ""))

    # ── Story Operations ─────────────────────────────────────

    def list_stories(self, epic_id: Optional[str] = None,
                     sprint: Optional[int] = None) -> list[Story]:
        # Quoted — custom type names may contain spaces (e.g. "User Story").
        jql_parts = [f'project = {self.project_key}', f'issuetype = "{self._jira_issue_type("story")}"']
        spec_clause = self._spec_filter_clause()
        if spec_clause:
            jql_parts.append(spec_clause)
        if epic_id:
            epic_key = self._resolve_id(epic_id)
            if epic_key:
                jql_parts.append(f'parent = {epic_key}')
        if sprint is not None:
            sprint_info = self._get_sprint_by_number(sprint)
            if sprint_info:
                jql_parts.append(f'sprint = {sprint_info["id"]}')
        jql = " AND ".join(jql_parts) + " ORDER BY created ASC"
        issues = self.transport.search_issues(jql)
        return [self._issue_to_story(i) for i in issues]

    def get_story(self, story_id: str) -> Optional[Story]:
        jira_key = self._resolve_id(story_id)
        if not jira_key:
            return None
        try:
            issue = self.transport.get_issue(jira_key)
            return self._issue_to_story(issue)
        except AdapterError:
            return None

    def create_ticket(self, story: Story, raw_text: str = "") -> Story:
        self._ensure_spec_writeable("create_ticket")
        # Detect entity type from ID prefix (B- → bug, T- → task, etc.)
        entity_type = _detect_entity_type(story.id)
        # Per-entity issue_type override wins; otherwise the ISSUE_TYPES default.
        issue_type = self._jira_issue_type(entity_type)

        labels = [story.id]
        title = _clean_title(story.title)
        tmpl_path = self._resolve_template_path(entity_type)
        description = _build_description(story.id, story.feature, raw_text or story.raw_text,
                                         template_path=tmpl_path)

        # Map priority
        priority = PRIORITY_MAP.get(story.priority)

        # Map size to story points
        story_points = SIZE_TO_POINTS.get(story.size)

        # Resolve parent epic
        parent_key = None
        if story.epic:
            parent_key = self._resolve_id(story.epic)

        # Resolve sprint
        sprint_id = None
        if story.sprint:
            try:
                sprint_info = self._get_sprint_by_number(int(story.sprint))
                if sprint_info:
                    sprint_id = sprint_info["id"]
            except (ValueError, TypeError):
                pass

        # Spec write side-effect (label append / component / epic-link fill-in).
        labels, parent_key, extra_fields = self._apply_spec_write_side_effect(
            labels=labels, parent_key=parent_key,
        )

        result = self.transport.create_issue(
            issue_type=issue_type,
            summary=title,
            description=description,
            parent_key=parent_key,
            labels=labels,
            priority=priority,
            sprint_id=sprint_id,
            story_points=story_points,
            fields=extra_fields or None,
        )
        jira_key = result.get("key", "")
        story.tracker_id = jira_key
        story.tracker_url = f"{self.transport.url}/browse/{jira_key}"
        self._save_id_mapping(story.id, jira_key, story.tracker_url)
        return story

    def update_story_status(self, story_id: str, status: str, *,
                            allow_skip: bool = False) -> Story:
        self._validate_status_transition(story_id, status, allow_skip)
        jira_key = self._resolve_id(story_id)
        if not jira_key:
            raise AdapterError(f"Story not found in ID map: {story_id}")

        # Per-spec status_map override wins over the built-in STATUS_MAP; the
        # alternatives-table fallback below still applies to whichever name we
        # resolve. Empty override ⇒ identical behavior to before.
        target = self._status_map_override.get(status) or STATUS_MAP.get(status)
        if target:
            try:
                self.transport.transition_issue(jira_key, target)
            except AdapterError:
                # Try common alternatives
                alternatives = {
                    "Backlog": ["To Do", "Open"],
                    "To Do": ["Backlog", "Open"],
                    "In Progress": ["Start Progress"],
                    "In Review": ["In Progress"],  # fallback if no "In Review" status
                    # #116 — fall back to In Review if the project's Jira
                    # workflow doesn't have an Awaiting Acceptance status.
                    "Awaiting Acceptance": ["In Review", "In Progress"],
                    "Done": ["Resolve Issue", "Close Issue", "Closed"],
                }
                transitioned = False
                for alt in alternatives.get(target, []):
                    try:
                        self.transport.transition_issue(jira_key, alt)
                        transitioned = True
                        break
                    except AdapterError:
                        continue
                if not transitioned:
                    raise

        # Write-through to local cache
        self._update_local_cache_status(story_id, status)

        story = self.get_story(story_id)
        if story:
            return story
        return Story(id=story_id, title=story_id, status=status)

    def update_story(self, story_id: str, **fields) -> Story:
        if "status" in fields:
            return self.update_story_status(story_id, fields["status"])
        jira_key = self._resolve_id(story_id)
        if not jira_key:
            raise AdapterError(f"Story not found: {story_id}")
        updates = {}
        if "title" in fields:
            updates["summary"] = _clean_title(fields["title"])
        if "priority" in fields and fields["priority"] in PRIORITY_MAP:
            updates["priority"] = PRIORITY_MAP[fields["priority"]]
        if "size" in fields and fields["size"] in SIZE_TO_POINTS:
            updates["story_points"] = SIZE_TO_POINTS[fields["size"]]
        if updates:
            self.transport.update_issue(jira_key, **updates)
        return self.get_story(story_id) or Story(id=story_id, title="")

    def get_acceptance_criteria(self, story_id: str) -> list[AcceptanceCriterion]:
        jira_key = self._resolve_id(story_id)
        if not jira_key:
            return []
        issue = self.transport.get_issue(jira_key)
        description = self._extract_description_text(issue)
        return self._parse_acs_from_description(description)

    def update_acceptance_criteria(self, story_id: str, ac_id: str,
                                   met: bool) -> AcceptanceCriterion:
        # Jira ACs are in the description; updating requires rewriting ADF
        # For now, return the requested state. Full ADF rewrite deferred.
        return AcceptanceCriterion(id=ac_id, text="", met=met)

    # ── Task & Bug Operations ────────────────────────────────

    def create_aux_ticket(self, ticket_type: str, title: str,
                          parent_id: Optional[str] = None, **fields) -> dict:
        self._ensure_spec_writeable("create_aux_ticket")
        issue_type = self._issue_type_overrides.get(ticket_type) or ISSUE_TYPES.get(ticket_type, "Task")
        labels = []
        if ticket_type == "enhancement":
            labels.append("enhancement")

        parent_key = None
        if parent_id:
            parent_key = self._resolve_id(parent_id)

        labels, parent_key, extra_fields = self._apply_spec_write_side_effect(
            labels=labels, parent_key=parent_key,
        )

        result = self.transport.create_issue(
            issue_type=issue_type,
            summary=title,
            description=fields.get("body", ""),
            parent_key=parent_key,
            labels=labels,
            fields=extra_fields or None,
        )
        jira_key = result.get("key", "")
        return {
            "id": jira_key, "title": title, "type": ticket_type,
            "url": f"{self.transport.url}/browse/{jira_key}",
        }

    def close_ticket(self, ticket_id: str, resolution: str = "") -> dict:
        jira_key = self._resolve_id(ticket_id) or ticket_id
        try:
            self.transport.transition_issue(jira_key, "Done")
        except AdapterError:
            try:
                self.transport.transition_issue(jira_key, "Closed")
            except AdapterError:
                self.transport.transition_issue(jira_key, "Resolve Issue")
        return {"id": ticket_id, "status": "DONE", "resolution": resolution}

    # ── Sprint Operations ────────────────────────────────────

    def list_sprints(self) -> list[SprintInfo]:
        if not self._board_id:
            return []
        raw_sprints = self.transport.list_sprints(self._board_id)
        result = []
        for sp in raw_sprints:
            name = sp.get("name", "")
            # Extract sprint number from name: "Sprint 1" -> 1
            num = self._extract_sprint_number(name)
            if num is None:
                continue

            # Get issues in this sprint
            issues = self.transport.get_sprint_issues(sp["id"])
            story_ids = self._extract_synaptory_ids(issues)

            result.append(SprintInfo(
                number=num,
                goal=sp.get("goal", name),
                dates=f"{sp.get('startDate', '')} to {sp.get('endDate', '')}".strip(" to "),
                story_ids=story_ids,
                story_count=len(story_ids),
                tracker_id=str(sp["id"]),
                tracker_url=f"{self.transport.url}/secure/RapidBoard.jspa?rapidView={self._board_id}&sprint={sp['id']}",
            ))
        return sorted(result, key=lambda s: s.number)

    def get_sprint(self, sprint_num: int) -> Optional[SprintInfo]:
        for s in self.list_sprints():
            if s.number == sprint_num:
                return s
        return None

    def create_sprint(self, sprint: SprintInfo) -> SprintInfo:
        if not self._board_id:
            raise AdapterError("No Scrum board found. Set tracker.jira.board_id.")
        name = f"{self._sprint_prefix}Sprint {sprint.number}"
        result = self.transport.create_sprint(
            board_id=self._board_id,
            name=name,
            goal=sprint.goal,
        )
        sprint_id = result.get("id", 0)
        sprint.tracker_id = str(sprint_id)
        self._save_id_mapping(f"SPRINT-{sprint.number}", str(sprint_id),
                              f"{self.transport.url}/secure/RapidBoard.jspa?sprint={sprint_id}")
        return sprint

    def get_sprint_backlog(self, sprint_num: int) -> list[Story]:
        sprint_info = self._get_sprint_by_number(sprint_num)
        if not sprint_info:
            return []
        issues = self.transport.get_sprint_issues(sprint_info["id"])
        # Accept the resolved story/task type names (issue_type overrides) as
        # well as the built-in defaults, so custom-typed stories stay in the
        # sprint backlog and boards mid-migration keep their default-typed ones.
        wanted = {
            self._jira_issue_type("story").lower(),
            self._jira_issue_type("task").lower(),
            "story", "task",
        }
        return [self._issue_to_story(i) for i in issues
                if self._get_issue_type(i).lower() in wanted]

    def assign_to_sprint(self, story_id: str, sprint_num: int) -> Story:
        jira_key = self._resolve_id(story_id)
        if not jira_key:
            raise AdapterError(f"Story not found: {story_id}")
        sprint_info = self._get_sprint_by_number(sprint_num)
        if not sprint_info:
            raise AdapterError(f"Sprint not found: {sprint_num}")
        self.transport.move_issues_to_sprint(sprint_info["id"], [jira_key])
        # Story stays in current status — transitions to TO_DO when sprint starts
        return self.get_story(story_id) or Story(id=story_id, title="")

    def remove_from_sprint(self, story_id: str, sprint_num: int) -> Story:
        # Jira: move to backlog = move to sprint 0 (backlog)
        jira_key = self._resolve_id(story_id)
        if not jira_key:
            raise AdapterError(f"Story not found: {story_id}")
        # Move to backlog via agile API
        try:
            self.transport._api_call(
                "POST", "/rest/agile/1.0/backlog/issue",
                body={"issues": [jira_key]},
            )
        except AdapterError:
            pass
        return self.get_story(story_id) or Story(id=story_id, title="")

    def close_sprint(self, sprint_num: int) -> SprintInfo:
        sprint_info = self._get_sprint_by_number(sprint_num)
        if not sprint_info:
            raise AdapterError(f"Sprint not found: {sprint_num}")
        self.transport.close_sprint(sprint_info["id"])
        return self.get_sprint(sprint_num) or SprintInfo(number=sprint_num, goal="")

    def move_incomplete_to_next(self, from_sprint: int, to_sprint: int) -> list[Story]:
        from_info = self._get_sprint_by_number(from_sprint)
        to_info = self._get_sprint_by_number(to_sprint)
        if not from_info or not to_info:
            return []
        issues = self.transport.get_sprint_issues(from_info["id"])
        # Terminal Jira status names: built-in defaults plus any overridden
        # names for the terminal canonical states (e.g. DONE → "Finished").
        done_names = {"done", "closed", "resolved"}
        for canon in ("DONE", "COMPLETED", "CANCELLED"):
            name = self._status_map_override.get(canon)
            if name:
                done_names.add(name.lower())
        incomplete_keys = []
        incomplete_stories = []
        for issue in issues:
            status = self._get_jira_status(issue).lower()
            if status not in done_names:
                key = issue.get("key", "")
                incomplete_keys.append(key)
                incomplete_stories.append(self._issue_to_story(issue))
        if incomplete_keys:
            self.transport.move_issues_to_sprint(to_info["id"], incomplete_keys)
        return incomplete_stories

    def get_sprint_metrics(self, sprint_num: int) -> SprintMetrics:
        stories = self.get_sprint_backlog(sprint_num)
        planned = len(stories)
        completed = sum(1 for s in stories if s.status in ("DONE", "COMPLETED"))
        in_progress = sum(1 for s in stories if s.status in ("IN_PROGRESS", "IN_REVIEW"))
        blocked = sum(1 for s in stories if s.status == "BLOCKED")
        return SprintMetrics(
            planned=planned, completed=completed,
            in_progress=in_progress, blocked=blocked,
            velocity=float(completed),
        )

    # ── Backlog Operations ───────────────────────────────────

    def get_backlog(self) -> list[BacklogItem]:
        # Quoted — custom type names may contain spaces (e.g. "User Story").
        parts = [f'project = {self.project_key}', f'issuetype = "{self._jira_issue_type("story")}"']
        spec_clause = self._spec_filter_clause()
        if spec_clause:
            parts.append(spec_clause)
        jql = " AND ".join(parts) + " ORDER BY rank ASC"
        issues = self.transport.search_issues(jql)
        return [self._issue_to_backlog_item(i) for i in issues]

    def query_tickets(self, query_filter: QueryFilter) -> list[BacklogItem]:
        jql_parts = [f'project = {self.project_key}']
        spec_clause = self._spec_filter_clause()
        if spec_clause:
            jql_parts.append(spec_clause)

        if query_filter.status:
            status_names = []
            for s in query_filter.status:
                # Per-spec status_map override wins over the built-in
                # STATUS_MAP (same resolution as update_story_status).
                mapped = self._status_map_override.get(s) or STATUS_MAP.get(s, s)
                status_names.append(f'"{mapped}"')
            jql_parts.append(f'status IN ({", ".join(status_names)})')

        if query_filter.priority:
            prio_names = []
            for p in query_filter.priority:
                mapped = PRIORITY_MAP.get(p, p)
                prio_names.append(f'"{mapped}"')
            jql_parts.append(f'priority IN ({", ".join(prio_names)})')

        if query_filter.ticket_type:
            type_names = [
                f'"{self._jira_issue_type(t)}"'
                for t in query_filter.ticket_type
            ]
            jql_parts.append(f'issuetype IN ({", ".join(type_names)})')

        if query_filter.sprint is not None:
            sprint_info = self._get_sprint_by_number(query_filter.sprint)
            if sprint_info:
                jql_parts.append(f'sprint = {sprint_info["id"]}')
            else:
                # #187 — a requested sprint that cannot be resolved must NOT be
                # silently dropped: doing so widens the query to every ticket
                # (e.g. `--sprint N --mine` returns all of the user's tickets
                # across all sprints). An unknown sprint has no tickets.
                print(
                    f"tracker(jira): sprint {query_filter.sprint} not found — "
                    "returning no tickets rather than dropping the sprint filter",
                    file=sys.stderr,
                )
                return []

        if query_filter.text:
            jql_parts.append(f'text ~ "{query_filter.text}"')

        if query_filter.assignee:
            if query_filter.assignee == "currentUser()":
                jql_parts.append("assignee = currentUser()")
            else:
                jql_parts.append(f'assignee = "{query_filter.assignee}"')

        jql = " AND ".join(jql_parts) + " ORDER BY rank ASC"
        issues = self.transport.search_issues(jql)
        return [self._issue_to_backlog_item(i) for i in issues]

    # ── Reporting Operations ─────────────────────────────────

    def get_velocity_data(self, num_sprints: int = 0) -> list[dict]:
        sprints = self.list_sprints()
        data = []
        for s in sprints:
            metrics = self.get_sprint_metrics(s.number)
            data.append({
                "sprint": s.number,
                "planned": metrics.planned,
                "completed": metrics.completed,
            })
        if num_sprints > 0:
            data = data[-num_sprints:]
        return data

    def get_sprint_report_data(self, sprint_num: int) -> dict:
        metrics = self.get_sprint_metrics(sprint_num)
        sprint = self.get_sprint(sprint_num)
        stories = self.get_sprint_backlog(sprint_num)
        return {
            "sprint_num": sprint_num,
            "sprint_goal": sprint.goal if sprint else f"Sprint {sprint_num}",
            "stories": {
                "planned": metrics.planned,
                "completed": metrics.completed,
                "in_progress": metrics.in_progress,
                "blocked": metrics.blocked,
                "completion_pct": round(
                    (metrics.completed / metrics.planned * 100) if metrics.planned > 0 else 0
                ),
                "status_by_story": [
                    {"id": s.id, "title": s.title, "status": s.status,
                     "priority": s.priority, "size": s.size, "feature": s.feature}
                    for s in stories
                ],
            },
        }

    def get_burndown_data(self, sprint_num: int) -> list[dict]:
        # Jira has native burndown — would require Jira Agile REST API
        # /rest/agile/1.0/board/{boardId}/sprint/{sprintId}/burndown
        # Deferred — return empty for now, Jira UI has this natively
        return []

    # ── Private Helpers ──────────────────────────────────────

    def _issue_to_epic(self, issue: dict) -> Epic:
        fields = issue.get("fields", {})
        synaptory_id = self._extract_synaptory_id(issue)
        return Epic(
            id=synaptory_id or issue.get("key", ""),
            title=fields.get("summary", ""),
            tracker_id=issue.get("key", ""),
            tracker_url=f"{self.transport.url}/browse/{issue.get('key', '')}",
        )

    def _issue_to_story(self, issue: dict) -> Story:
        fields = issue.get("fields", {})
        synaptory_id = self._extract_synaptory_id(issue)

        # Status
        jira_status = self._get_jira_status(issue)
        # Honor the per-spec status_map override on read-back first (so a
        # custom name like "WAITING FOR PO ACCEPTANCE" maps to its canonical
        # state), then fall back to the built-in STATUS_REVERSE table. Matching
        # is normalized (case + separator insensitive), so "IN REVIEW" reads
        # back to IN_REVIEW without needing a status_map entry.
        norm = _norm_status(jira_status)
        status = (
            self._status_reverse_override.get(norm)
            or _STATUS_REVERSE_NORM.get(norm, "TODO")
        )

        # Priority
        jira_priority = ""
        if fields.get("priority"):
            jira_priority = fields["priority"].get("name", "")
        priority = PRIORITY_REVERSE.get(jira_priority, "")

        # Size from story points
        points = fields.get("story_point_estimate") or fields.get("story_points")
        size = ""
        if points is not None:
            try:
                size = POINTS_TO_SIZE.get(int(points), str(int(points)))
            except (ValueError, TypeError):
                pass

        # Sprint
        sprint_str = ""
        sprint_field = fields.get("sprint")
        if sprint_field:
            sprint_name = sprint_field.get("name", "") if isinstance(sprint_field, dict) else ""
            num = self._extract_sprint_number(sprint_name)
            if num is not None:
                sprint_str = str(num)

        # Feature from parent epic
        feature = ""
        parent = fields.get("parent")
        if parent:
            parent_key = parent.get("key", "")
            # Try to resolve parent to synaptory epic ID
            for hid, mapping in self._load_id_map().items():
                if mapping.get("jira_key") == parent_key:
                    feature = hid
                    break

        # ACs from description
        description_text = self._extract_description_text(issue)
        acs = self._parse_acs_from_description(description_text)

        # Assignee
        assignee_field = fields.get("assignee")
        assignee_value = None
        if assignee_field and isinstance(assignee_field, dict):
            assignee_value = (
                assignee_field.get("emailAddress")
                or assignee_field.get("displayName")
            )

        return Story(
            id=synaptory_id or issue.get("key", ""),
            title=fields.get("summary", ""),
            feature=feature,
            status=status,
            priority=priority,
            size=size,
            sprint=sprint_str,
            ac_count=len(acs),
            acceptance_criteria=acs,
            assignee=assignee_value,
            tracker_id=issue.get("key", ""),
            tracker_url=f"{self.transport.url}/browse/{issue.get('key', '')}",
        )

    def _issue_to_backlog_item(self, issue: dict) -> BacklogItem:
        story = self._issue_to_story(issue)
        return BacklogItem(
            id=story.id, title=story.title, feature=story.feature,
            priority=story.priority, status=story.status,
            size=story.size, sprint=story.sprint, assignee=story.assignee,
        )

    @staticmethod
    def _extract_synaptory_id(issue: dict) -> str:
        """Extract synaptory ID from label.

        Looks for labels matching synaptory ID patterns (US-NNN, EPIC-NNN, etc.)
        directly — no prefix needed.
        """
        fields = issue.get("fields", {})
        labels = fields.get("labels", [])
        for label in labels:
            name = label if isinstance(label, str) else ""
            if re.match(r'^(US|EPIC|FEAT|BUG|ENH|TASK|S\d+)-\w+$', name):
                return name
        # Fallback: check description metadata
        description = fields.get("description", "")
        if isinstance(description, str):
            m = re.search(r'synaptory:\s*`?(\S+?)`?(?:\s|$)', description)
            if m:
                return m.group(1)
        # Legacy: ref: prefix
        for label in labels:
            name = label if isinstance(label, str) else ""
            if name.startswith("ref:"):
                return name[4:]
        return ""

    @staticmethod
    def _extract_synaptory_ids(issues: list[dict]) -> list[str]:
        return [hid for i in issues if (hid := JiraAdapter._extract_synaptory_id(i))]

    @staticmethod
    def _get_jira_status(issue: dict) -> str:
        fields = issue.get("fields", {})
        status = fields.get("status", {})
        return status.get("name", "") if isinstance(status, dict) else ""

    @staticmethod
    def _get_issue_type(issue: dict) -> str:
        fields = issue.get("fields", {})
        itype = fields.get("issuetype", {})
        return itype.get("name", "") if isinstance(itype, dict) else ""

    def _extract_sprint_number(self, name: str) -> Optional[int]:
        """Extract the synaptory sprint number from a Jira sprint name.

        Prefix-aware and separator-tolerant:
          - When a spec prefix is set (e.g. `VA_`), only names starting with it
            are in-scope; the prefix is stripped before parsing, and names
            without it return None. This is what scopes list/get/velocity reads
            to the active spec on a board shared by multiple specs.
          - Accepts `_` or whitespace as the `Sprint`↔number separator, so both
            `VA_Sprint 1` and `VA_Sprint_1` parse (see #102). Empty prefix ⇒
            legacy `Sprint N` parsing, unchanged.
        """
        if self._sprint_prefix:
            if not name.startswith(self._sprint_prefix):
                return None
            name = name[len(self._sprint_prefix):]
        m = re.search(r'Sprint[_\s]+(\d+)', name, re.IGNORECASE)
        if m:
            return int(m.group(1))
        return None

    @staticmethod
    def _extract_description_text(issue: dict) -> str:
        """Extract plain text from a Jira issue description (ADF or string)."""
        fields = issue.get("fields", {})
        desc = fields.get("description", "")
        if isinstance(desc, str):
            return desc
        if isinstance(desc, dict):
            # ADF document — extract text content
            return JiraAdapter._adf_to_text(desc)
        return ""

    @staticmethod
    def _adf_to_text(adf: dict) -> str:
        """Convert ADF document to plain text."""
        parts = []
        for node in adf.get("content", []):
            node_type = node.get("type", "")
            if node_type == "paragraph":
                text = "".join(
                    c.get("text", "") for c in node.get("content", [])
                    if c.get("type") == "text"
                )
                if text:
                    parts.append(text)
            elif node_type in ("heading",):
                level = node.get("attrs", {}).get("level", 2)
                text = "".join(
                    c.get("text", "") for c in node.get("content", [])
                    if c.get("type") == "text"
                )
                parts.append(f"{'#' * level} {text}")
            elif node_type == "bulletList":
                for item in node.get("content", []):
                    for p in item.get("content", []):
                        text = "".join(
                            c.get("text", "") for c in p.get("content", [])
                            if c.get("type") == "text"
                        )
                        parts.append(f"- {text}")
            elif node_type == "taskList":
                for item in node.get("content", []):
                    state = item.get("attrs", {}).get("state", "TODO")
                    text = "".join(
                        c.get("text", "") for c in item.get("content", [])
                        if c.get("type") == "text"
                    )
                    check = "x" if state == "DONE" else " "
                    parts.append(f"- [{check}] {text}")
        return "\n".join(parts)

    @staticmethod
    def _parse_acs_from_description(text: str) -> list[AcceptanceCriterion]:
        """Parse acceptance criteria from description text."""
        acs = []
        for line in text.splitlines():
            stripped = line.strip()
            # Match: - [ ] AC-1: text  or  - [x] **AC-1: text**
            m = re.match(r'- \[([xX ])\]\s*\*?\*?AC-(\w+):?\s*(.*?)\*?\*?\s*$', stripped)
            if m:
                acs.append(AcceptanceCriterion(
                    id=f"AC-{m.group(2)}",
                    text=m.group(3).strip(),
                    met=m.group(1).lower() == "x",
                ))
                continue
            # Match: **AC-1 — title:** or **AC-1: text**
            m2 = re.match(r'\*\*AC-(\w+)\s*[—–\-:]?\s*(.*?)\*\*', stripped)
            if m2:
                acs.append(AcceptanceCriterion(
                    id=f"AC-{m2.group(1)}",
                    text=m2.group(2).strip().rstrip(":").strip(),
                ))
        return acs

    def _get_sprint_by_number(self, sprint_num: int) -> Optional[dict]:
        """Get a Jira sprint dict by its synaptory sprint number."""
        # Check ID map first
        entry = self._load_id_map().get(f"SPRINT-{sprint_num}")
        if entry:
            sprint_id = entry.get("jira_key") or entry.get("github_number")
            if sprint_id:
                try:
                    return self.transport.get_sprint(int(sprint_id))
                except (AdapterError, ValueError):
                    pass

        # Fallback: search all sprints
        if self._board_id:
            for sp in self.transport.list_sprints(self._board_id):
                num = self._extract_sprint_number(sp.get("name", ""))
                if num == sprint_num:
                    return sp
        return None

    def _load_id_map(self) -> dict:
        if self._id_map is not None:
            return self._id_map
        if self._id_map_path.exists():
            try:
                self._id_map = json.loads(self._id_map_path.read_text(encoding="utf-8"))
            except Exception:
                self._id_map = {}
        else:
            self._id_map = {}
        return self._id_map

    def _save_id_mapping(self, synaptory_id: str, jira_key: str, url: str = "") -> None:
        id_map = self._load_id_map()
        id_map[synaptory_id] = {"jira_key": jira_key, "jira_url": url}
        self._id_map_path.parent.mkdir(parents=True, exist_ok=True)
        self._id_map_path.write_text(json.dumps(id_map, indent=2), encoding="utf-8")

    def _resolve_id(self, synaptory_id: str) -> Optional[str]:
        """Resolve a synaptory ID to a Jira issue key."""
        id_map = self._load_id_map()
        entry = id_map.get(synaptory_id)
        if entry:
            return entry.get("jira_key")
        return None

    def _load_backlog_order(self) -> list[str]:
        if self._backlog_order_path.exists():
            try:
                return json.loads(self._backlog_order_path.read_text(encoding="utf-8"))
            except Exception:
                return []
        return []

    def _save_backlog_order(self, order: list[str]) -> None:
        self._backlog_order_path.parent.mkdir(parents=True, exist_ok=True)
        self._backlog_order_path.write_text(json.dumps(order, indent=2), encoding="utf-8")
